<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">&#x2190;</text><text class="nav-title">&#x989C;&#x8272;&#x8F6C;&#x6362;</text><text class="nav-icon"> </text></view></view><view class="content"><view class="preview-box" :style="{background: hexValue}"></view><view class="input-tabs"><view class="tab-btn" :class="{active: tab==='hex'}" @click="tab='hex'">HEX</view><view class="tab-btn" :class="{active: tab==='rgb'}" @click="tab='rgb'">RGB</view><view class="tab-btn" :class="{active: tab==='hsl'}" @click="tab='hsl'">HSL</view></view><view v-if="tab==='hex'" class="input-section"><view class="coef-row"><text class="coef-label">HEX</text><input class="coef-input" v-model="hexValue" placeholder="#FF5500" /></view></view><view v-if="tab==='rgb'" class="input-section"><view class="coef-row"><text class="coef-label">R</text><input class="coef-input" type="number" v-model.number="r" min="0" max="255" /></view><view class="coef-row"><text class="coef-label">G</text><input class="coef-input" type="number" v-model.number="g" min="0" max="255" /></view><view class="coef-row"><text class="coef-label">B</text><input class="coef-input" type="number" v-model.number="b" min="0" max="255" /></view></view><view v-if="tab==='hsl'" class="input-section"><view class="coef-row"><text class="coef-label">H</text><input class="coef-input" type="number" v-model.number="h" min="0" max="360" /></view><view class="coef-row"><text class="coef-label">S</text><input class="coef-input" type="number" v-model.number="s" min="0" max="100" /></view><view class="coef-row"><text class="coef-label">L</text><input class="coef-input" type="number" v-model.number="l" min="0" max="100" /></view></view><view class="format-results"><view class="fmt-card" v-for="f in formats" :key="f.label"><text class="fmt-label">{{f.label}}</text><text class="fmt-value" @click="copyText(f.value)">{{f.value}}</text></view></view></view></view></template><script setup>import { ref, computed, watch, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const tab = ref("hex")
const hexValue = ref("#6366f1")
const r = ref(99); const g = ref(102); const b = ref(241)
const h = ref(239); const s = ref(84); const l = ref(67)
const formats = computed(function() { var hex = hexValue.value; var rgb = "rgb(" + r.value + ", " + g.value + ", " + b.value + ")"; var hsl = "hsl(" + h.value + ", " + s.value + "%, " + l.value + "%)"; var cmyk = rgbToCmyk(r.value, g.value, b.value); return [{label:"HEX", value: hex}, {label:"RGB", value: rgb}, {label:"HSL", value: hsl}, {label:"CMYK", value: cmyk}] })
function goBack() { uni.navigateBack() }
function copyText(t) { uni.setClipboardData({ data: t, success: function() { uni.showToast({ title: "&#x5DF2;&#x590D;&#x5236;", icon: "success" }) } }) }
function rgbToCmyk(r, g, b) { var rr = r/255, gg = g/255, bb = b/255; var k = 1 - Math.max(rr, gg, bb); if (k === 1) return "cmyk(0%, 0%, 0%, 100%)"; var c = (1-rr-k)/(1-k), m = (1-gg-k)/(1-k), y = (1-bb-k)/(1-k); return "cmyk(" + Math.round(c*100) + "%, " + Math.round(m*100) + "%, " + Math.round(y*100) + "%, " + Math.round(k*100) + "%)" }
watch(hexValue, function(v) { if (/^#[0-9A-Fa-f]{6}$/.test(v)) { r.value = parseInt(v.slice(1,3),16); g.value = parseInt(v.slice(3,5),16); b.value = parseInt(v.slice(5,7),16) } })
watch([r,g,b], function() { hexValue.value = "#" + [r.value,g.value,b.value].map(function(v){return v.toString(16).padStart(2,'0')}).join('') })
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#ec4899,#db2777);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.preview-box{height:200rpx;border-radius:16rpx;margin-bottom:24rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.08)}.input-tabs{display:flex;gap:8rpx;margin-bottom:16rpx}.tab-btn{flex:1;padding:16rpx;text-align:center;background:#fff;border-radius:12rpx;font-size:26rpx;color:#666}.tab-btn.active{background:linear-gradient(135deg,#ec4899,#db2777);color:#fff}.input-section{background:#fff;border-radius:16rpx;padding:24rpx;margin-bottom:16rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.coef-row{display:flex;align-items:center;margin-bottom:12rpx}.coef-label{font-size:26rpx;color:#666;width:60rpx}.coef-input{flex:1;height:72rpx;background:#f5f7fb;border-radius:8rpx;padding:0 16rpx;font-size:28rpx;border:2rpx solid #eee}.format-results{display:grid;grid-template-columns:1fr 1fr;gap:12rpx}.fmt-card{background:#fff;border-radius:12rpx;padding:20rpx;box-shadow:0 4rpx 16rpx rgba(0,0,0,.04)}.fmt-label{font-size:22rpx;color:#999;display:block;margin-bottom:8rpx}.fmt-value{font-size:26rpx;color:#333;font-family:monospace;font-weight:600}</style>